const StatusStateIconEntry* FindStatusStateIcon(int priority, int status)
{
    for (const StatusStateIconEntry& entry : kStatusStateIconEntries) {
        if (entry.priority == priority && entry.status == status) {
            return &entry;
        }
    }
    return nullptr;
}

