            sprite.right = right; sprite.bottom = bottom;
            sprite.oow = static_cast<float>(1.0 / ((bottom - y) * slope + z) + 0.0000099999997);
            sprite.oowup = static_cast<float>(1.0 / ((top - y) * slope + z) + 0.0000099999997);
