    prim->m_heightSize = 0.18000001f;
    prim->m_alpha = 0.0f; prim->m_maxAlpha = 200.0f;
    prim->m_alphaSpeed = static_cast<float>(prim->m_maxAlpha*0.050000001);
    prim->m_fadeOutCnt = prim->m_duration-20;
