void CRagEffect::ApplyEffectTexture(const char* textureName, int variant)
{
    if (textureName == nullptr) {
        return;
    }
    CRenderObject* master = ResolveCurrentMaster();
    const vector3d origin = master != nullptr ? master->m_pos : m_cachedPos;
    m_effectPos = origin;
    m_cachedPos = origin;
    for (CEffectPrim* existing : m_primList) {
        if (existing != nullptr && existing->m_type == static_cast<EFFECTPRIMID>(kPrimTypeEffectTexture)) {
            existing->m_pos = origin;
        }
    }
    if (m_stateCnt != 0) {
        return;
    }
    CEffectPrim* prim = LaunchEffectPrim(static_cast<EFFECTPRIMID>(kPrimTypeEffectTexture), vector3d{});
    if (prim == nullptr) {
        return;
    }
    prim->m_renderFlag = 5;
    if (variant == 100) {
        prim->m_renderFlag = 257;
    }
    prim->m_duration = m_duration;
    prim->m_size = 0.0f;
    prim->m_pos = origin;
    prim->m_texture.push_back(g_texMgr.GetTexture(textureName, false));
    EffectGi& gi = prim->m_gi[0];
    gi.life = 1;
    gi.process = 0;
    if (variant == 2) {
        gi.distance = 10.0f;
        gi.arcBaselineY = origin.y - 10.0f;
        gi.flag[2] = 2;
        gi.height[10] = 0.0f;
        gi.fullDisplayAngle = 135;
    } else if (variant == 3) {
        gi.distance = 8.0f;
        gi.arcBaselineY = origin.y - 30.0f;
        gi.flag[2] = 3;
        gi.height[10] = 2.0f;
        gi.fullDisplayAngle = 155;
    } else if (variant == 4) {
        gi.distance = 6.0f;
        gi.arcBaselineY = origin.y - 30.0f;
        gi.flag[2] = 0;
        gi.height[10] = 0.0f;
        gi.fullDisplayAngle = 135;
    } else if (variant == 14) {
        gi.distance = m_param[0] > 0.0f ? m_param[0] : 30.0f;
        gi.arcBaselineY = origin.y;
        gi.flag[2] = 4;
        gi.height[10] = 0.0f;
        gi.fullDisplayAngle = static_cast<short>(rand() % 360);
    } else if (variant == 100) {
        gi.distance = 50.0f;
        gi.flag[2] = 100;
        gi.height[10] = 0.0f;
        gi.fullDisplayAngle = 45;
    } else {
        gi.distance = 8.0f;
        gi.arcBaselineY = origin.y - 30.0f;
        gi.flag[2] = 0;
        gi.height[10] = 1.0f;
        gi.fullDisplayAngle = 120;
    }
    gi.height[8] = 0.0f;
    gi.alphaB = 0;
    gi.sparkX = origin.x;
    gi.sparkZ = origin.z + (variant == 100 ? 100.0f : 0.0f);
    if (variant == 100) {
        gi.arcBaselineY = origin.y + 100.0f;
    }
    gi.rotStart = static_cast<short>(rand() % 360);
    gi.flag[0] = 0;
    gi.flag[4] = static_cast<u8>(variant == 4 ? 1 : variant);
}

