        if (mode && mode->m_world && mode->m_world->m_player) {
            const vector3d& listener = mode->m_world->m_player->m_pos;
            PlayWave("effect\\", m_effectPos.x - listener.x, 0.0f, m_effectPos.z - listener.z,
                250, 40, 1.0f);
        }
